# frozen_string_literal: true

# Core namespace for the CDD Ruby compiler and OpenAPI toolchain.
module Cdd
  # Shared Ripper token scanning utilities used across CDD parsers.
  module TokenScanner
    # HTTP method verbs supported in Sinatra and OpenAPI 3.2.0 route definitions.
    SINATRA_HTTP_VERBS = %w[get post put delete patch options head trace query].freeze

    # Preceding token types or values that disqualify an identifier from being a top-level Sinatra route.
    DISQUALIFYING_PREV_TYPES = %i[on_symbeg on_period on_ident].freeze

    # Internal scaffolding class names generated by CDD that are not OpenAPI domain models.
    SCAFFOLDING_CLASSES = %w[CliParser Factory DatabaseConnection ClientSdk ClientSdkMcpAdapter].freeze

    # Checks whether a class name is an internal scaffolding or DAO class.
    #
    # @param name [String] the Ruby class name
    # @return [Boolean] true if the class is internal scaffolding
    def self.scaffolding_class?(name)
      SCAFFOLDING_CLASSES.include?(name) || name.end_with?('Dao')
    end

    # Parses a `@schema_one_of` or `@schema_any_of` comment body into an OpenAPI composition schema hash.
    #
    # @param composition_key [String] either 'oneOf' or 'anyOf'
    # @param rest [String] the remainder of the docstring comment after the schema name
    # @return [Hash{String => Object}] the constructed OpenAPI schema definition
    def self.parse_composition_schema(composition_key, rest)
      parts = rest.strip.split(/\s+/)
      refs_part = parts.shift || ''
      refs = refs_part.split(',').map { |r| { '$ref' => "#/components/schemas/#{r.strip}" } }
      schema = { composition_key => refs }

      discriminator = parse_discriminator_options(parts)
      schema['discriminator'] = discriminator if discriminator
      schema
    end

    # Parses discriminator options (`discriminator:`, `mapping:`, `defaultMapping:`) from token parts.
    #
    # @param parts [Array<String>] space-separated key:value tokens
    # @return [Hash{String => Object}, nil] discriminator hash or nil if none present
    def self.parse_discriminator_options(parts)
      discriminator = nil
      parts.each do |part|
        if part.start_with?('discriminator:')
          discriminator ||= {}
          discriminator['propertyName'] = part.split(':', 2).last
        elsif part.start_with?('mapping:')
          discriminator ||= {}
          mapping = {}
          part.split(':', 2).last.split(',').each do |pair|
            k, v = pair.split(':')
            mapping[k] = "#/components/schemas/#{v}"
          end
          discriminator['mapping'] = mapping
        elsif part.start_with?('defaultMapping:')
          discriminator ||= {}
          discriminator['defaultMapping'] = "#/components/schemas/#{part.split(':', 2).last}"
        end
      end
      discriminator
    end

    # Parses Sinatra-style route declarations from a Ripper token stream into the IR.
    #
    # @param tokens [Array<Array>] Ripper lexed token stream
    # @param ir [Cdd::IR] Intermediate Representation to populate
    # @return [void]
    def self.parse_sinatra_routes(tokens, ir)
      tokens.each_with_index do |token, idx|
        next unless token[1] == :on_ident && SINATRA_HTTP_VERBS.include?(token[2].downcase)

        path = extract_route_path_literal(tokens, idx)
        next unless path&.start_with?('/') && !path.start_with?('/mcp/')

        register_sinatra_route(ir, token[2].downcase, path)
      end
    end

    # Extracts the string literal path argument following a route verb token.
    #
    # @param tokens [Array<Array>] Ripper lexed token stream
    # @param idx [Integer] route verb token index
    # @return [String, nil] the route path string or nil if not a route literal
    def self.extract_route_path_literal(tokens, idx)
      cursor = skip_spaces(tokens, idx + 1)
      nxt = tokens[cursor]
      cursor = skip_spaces(tokens, cursor + 1) if nxt && nxt[1] == :on_lparen
      target = tokens[cursor]
      return nil unless target && %i[on_tstring_beg on_tstring_content].include?(target[1])

      path_token = tokens[cursor..(cursor + 2)].find { |t| t[1] == :on_tstring_content }
      path_token ? path_token[2] : nil
    end

    # Advances the token index past any `:on_sp` whitespace tokens.
    #
    # @param tokens [Array<Array>] Ripper lexed token stream
    # @param start_idx [Integer] starting index
    # @return [Integer] index of the first non-space token
    def self.skip_spaces(tokens, start_idx)
      cursor = start_idx
      cursor += 1 while cursor < tokens.size && tokens[cursor][1] == :on_sp
      cursor
    end

    # Registers an extracted Sinatra route and its `:param` path parameters in the IR.
    #
    # @param ir [Cdd::IR] Intermediate Representation
    # @param method [String] lowercase HTTP method
    # @param path [String] Sinatra route path
    # @return [void]
    def self.register_sinatra_route(ir, method, path)
      openapi_path = path.gsub(/:([a-zA-Z0-9_]+)/, '{\1}')
      ir.openapi_spec['paths'] ||= {}
      ir.openapi_spec['paths'][openapi_path] ||= {}
      ir.openapi_spec['paths'][openapi_path][method] ||= {
        'responses' => { '200' => { 'description' => 'OK' } }
      }

      params = (ir.openapi_spec['paths'][openapi_path][method]['parameters'] ||= [])
      path.scan(/:([a-zA-Z0-9_]+)/).flatten.each do |param_name|
        next if params.any? { |p| p['name'] == param_name }

        params << {
          'name' => param_name,
          'in' => 'path',
          'required' => true,
          'schema' => { 'type' => 'string' }
        }
      end
    end
  end
end
